ALTER TABLE staff_task_events DROP CONSTRAINT staff_task_events_event_type_check;
ALTER TABLE staff_task_events ADD CONSTRAINT staff_task_events_event_type_check
  CHECK (event_type IN ('CREATED','UPDATED','ASSIGNED','REASSIGNED','COMMENTED','STARTED','COMPLETED','SUBMITTED_FOR_APPROVAL','APPROVED','REJECTED','CHANGES_REQUESTED','CANCELLED','REOPENED','ESCALATION_REASSIGNED','ESCALATED','APPROVAL_EXPIRED','APPROVER_REASSIGNED'));
